+    for _k in kartlar_:
+        for _i in _k.get("isler") or []:
+            _i["model_ad"] = model_sec.get((_i.get("no"), _i.get("sahip") or "")) or ""
     for k in kartlar_:
         if k["tip"] not in ("istek", "soru_ajana"):
