INSERT INTO "olay" VALUES(6357,'915d303e41ee4cb59fa908401d277926','asli','a73d2720732d43969b666a7e8d9ebf6d','arac','Bash
mkdir -p .ofis/karalama && cat > .ofis/karalama/panel_duzelt.py <<''EOF''
import sys
